    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp cannot be negative");
    }

    // Assuming a map to store the last printed timestamp for each message
    Map<String, Integer> messageTimestampMap = new HashMap<>();

    if (!messageTimestampMap.containsKey(message) || messageTimestampMap.get(message) + 10 <= timestamp) {
        messageTimestampMap.put(message, timestamp);
        return true;
    } else {
        return false;
    }
}

