@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null || dir.isEmpty()) {
        throw new IllegalArgumentException("Directory cannot be null or empty");
    }
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a valid directory");
    }
    File[] files = directory.listFiles((d, name) -> name.endsWith(".jar"));
    if (files != null) {
        for (File file : files) {
            try {
                cpV.add(file.toURI().toURL());
            } catch (MalformedURLException e) {
                System.err.println("Error adding file to classpath: " + file.getAbsolutePath());
                e.printStackTrace();
            }
        }
    }
}

