public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '"':
                    result.append('"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        result.append((char) codePoint);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

