        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    if (nameStart >= buf.length()) {
        // If nameStart is beyond the length of the buffer, do nothing
        return;
    }

    // Find the end of the first word
    int end = nameStart;
    while (end < buf.length() && Character.isLetterOrDigit(buf.charAt(end))) {
        end++;
    }

    if (end == nameStart) {
        // No valid word to abbreviate
        return;
    }

    // Abbreviate the name by keeping the first character and appending a dot
    char firstChar = buf.charAt(nameStart);
    buf.replace(nameStart, end, String.valueOf(firstChar) + ".");
}

